import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();
  const [activeMenu, setActiveMenu] = useState("Home");

  const menuItems = [
    { name: "Home" },
    { name: "Profile" },
    { name: "Settings" },
    { name: "About" },
    { name: "Logout" }
  ];

  const handleMenuClick = (item) => {
    setActiveMenu(item.name);
    if (item.name === "Logout") {
      localStorage.removeItem("user");
      navigate("/login");
    }
  };

  return (
    <div className="homepage-container">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-logo">🚗 Parking System</div>
        {menuItems.map((item, index) => (
          <button
            key={index}
            className={`sidebar-btn ${activeMenu === item.name ? "active" : ""}`}
            onClick={() => handleMenuClick(item)}
          >
            {item.name}
          </button>
        ))}
      </aside>

      {/* Main Content */}
      <main className="main-content">
        <div className="welcome-card">
          <h1>{activeMenu}</h1>
          <p>
            {activeMenu === "Home" && "Welcome! Use the sidebar to navigate through the system and manage your parking slots efficiently."}
            {activeMenu === "Profile" && "View and update your profile details here."}
            {activeMenu === "Settings" && "Change system preferences and settings here."}
            {activeMenu === "About" && "This system helps you book parking slots quickly and efficiently."}
          </p>
          {activeMenu === "Home" && (
            <button className="start-btn" onClick={() => navigate("/booking")}>
              Start Booking
            </button>
          )}
        </div>
      </main>
    </div>
  );
}

export default HomePage;
